  sigh:  {name: 'Quick reset', sub: 'Two breaths in, long out', steps: [['in', 3], ['top', 1.5], ['out', 7]]},
  sleep: {name: 'Deep relax', sub: 'In 4, hold 7, out 8', steps: [['in', 4], ['hold', 7], ['out', 8]]},
